/* ───────── STRATEGIES ───────── */
"private-equity":{g:"Strategies",eyebrow:"Strategy",h1:"Private equity: owning the <em>unlisted</em>",lede:"Buying meaningful stakes in private companies, helping them grow, and selling at a higher value — usually over five to eight years.",
 facts:[["Wrapper","AIF Category II"],["Horizon","7–10 years"],["Target net IRR","15–20%"],["Liquidity","Very low"]],
 s:[
  {t:"prose",h:"Where the returns come from",b:"<p>PE returns have three engines: <b>earnings growth</b> (the company gets bigger and more profitable), <b>multiple expansion</b> (the market pays more per rupee of earnings at exit than at entry) and <b>leverage</b> (less common in India than in US buyouts). The best managers underwrite to growth alone and treat multiple expansion as a bonus.</p>"},
  {t:"steps",h:"What to ask a PE manager",items:[["Prior funds","Net IRR, DPI and TVPI of each previous fund, by vintage."],["Attribution","How much return came from growth vs rising multiples?"],["Losses","How many deals lost money, and what did they learn?"],["Team stability","Are the partners who made past returns still there?"]]},
  {t:"live",h:"PE and venture strategies on AltMarket",f:{themes:["Venture & PE"]}}
 ],rel:["aif-cat-2","venture","carry-explained"]},
"private-credit":{g:"Strategies",eyebrow:"Strategy",h1:"Private credit: lending, <em>privately</em>",lede:"Funds that lend directly to companies and projects — performing credit, structured deals, special situations — for yields well above bank deposits and listed bonds.",
 facts:[["Wrapper","AIF Category II"],["Horizon","3–5 years"],["Target gross yield","12–16%"],["Cash flow","Quarterly distributions typical"]],
 s:[
  {t:"prose",h:"Why companies borrow from funds",b:"<p>Banks lend against rigid rules; private credit funds lend against a thesis. A mid-sized company buying a competitor, a real-estate developer needing last-mile funding, a promoter refinancing a pledge — each will pay a premium for speed and flexibility. That premium is your yield.</p><p>The flip side: there's no rating agency doing the work for you. Security cover, covenants and the manager's ability to enforce them determine what you get back if something goes wrong.</p>"},
  {t:"table",h:"The credit spectrum",head:["Type","Typical yield","Risk"],rows:[["Performing senior secured","11–13%","Lower — first charge on assets"],["Structured / mezzanine","14–17%","Moderate — subordinated, equity kicker"],["Special situations / distressed","18%+","High — restructuring and recovery"]]},
  {t:"live",h:"Credit and income strategies on AltMarket",f:{themes:["Credit & debt"]}}
 ],rel:["aif-cat-2","first-time"]},
"long-short":{g:"Strategies",eyebrow:"Strategy",h1:"Long-short: profit from <em>both</em> sides",lede:"Buy what's undervalued, short what's overvalued, and let the spread do the work. A way to own equity with a smaller share of the market's swings.",
 facts:[["Wrappers","AIF Cat III, SIF"],["Horizon","3+ years"],["Net exposure","Usually 30–90%"],["Aim","Smoother equity returns"]],
 s:[
  {t:"prose",h:"The idea in one example",b:"<p>Say a manager likes Bank A and dislikes Bank B. She buys ₹10 lakh of A and shorts ₹5 lakh of B. If banks fall 10% together, she loses ₹1 lakh on A but gains ₹50,000 on B — a ₹50,000 loss instead of ₹1 lakh. If she's right about the pair, A rises and B falls, and she profits on both legs.</p><p>Done well, long-short funds lose less in crashes and still participate in rallies. Done badly, they lose on both legs and pay financing costs for the privilege.</p>"},
  {t:"live",h:"Long-short funds on AltMarket",f:{themes:["Long-short"]}}
 ],rel:["aif-cat-3","sif","long-short-explained"]},
"long-only":{g:"Strategies",eyebrow:"Strategy",h1:"Long-only: <em>conviction</em>, concentrated",lede:"Portfolios of 15–30 stocks held for years — the dominant PMS style in India, and the purest test of a manager's stock-picking.",
 facts:[["Wrappers","PMS, AIF Cat III"],["Stocks","15–30 typical"],["Horizon","5+ years"],["Benchmark","BSE 500 / Nifty 50 TRI"]],
 s:[
  {t:"prose",h:"Styles you'll meet",b:"<p><b>Quality growth</b> managers buy high-return businesses and sit tight. <b>Value</b> managers buy cheap and wait for re-rating. <b>GARP</b> blends the two. <b>Small and micro-cap</b> specialists hunt where research coverage is thin. <b>Quant and factor</b> strategies let rules, not stories, pick the stocks.</p><p>Each style has seasons. A value manager can trail for three years and still be doing the job well — which is why we show returns across every period, not just the last twelve months.</p>"},
  {t:"live",h:"Long-only equity leaders by 3-year return",f:{types:["PMS"],themes:["Small cap","Mid cap","Multi / flexi","Large cap","Value"]},sort:"y3"}
 ],rel:["pms","direct-vs-pms","reading-returns"]},
venture:{g:"Strategies",eyebrow:"Strategy",h1:"Venture capital: backing the <em>next decade</em>",lede:"Minority stakes in startups at seed to growth stage, where a single breakout can return the whole fund.",
 facts:[["Wrapper","AIF Category I"],["Horizon","8–12 years"],["Outcome spread","Very wide"],["Minimum","₹1 crore (angel ₹25 lakh)"]],
 s:[
  {t:"prose",h:"The power law",b:"<p>In a typical venture portfolio of 25 companies, perhaps half will fail, a handful will return capital, and one or two will generate most of the gains. Picking the manager with access to those one or two is everything — and the best funds are often oversubscribed.</p>"},
  {t:"live",h:"Venture and growth funds on AltMarket",f:{themes:["Venture & PE"]}}
 ],rel:["aif-cat-1","private-equity"]},

